import { SITE_URL } from "@/lib/site";
import { sitemapIds } from "@/lib/sitemap-groups";

export const revalidate = 3600;

/**
 * The sitemap index at /sitemap.xml. Next.js has no first-class "sitemap
 * index" file convention, so this route handler emits it directly and the
 * shards live at /sitemap/{id}.xml (generated by app/sitemap/[id]/sitemap.ts).
 */
export async function GET() {
  const ids = await sitemapIds();
  const lastmod = new Date().toISOString();
  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${ids
  .map(
    ({ id }) =>
      `  <sitemap><loc>${SITE_URL}/sitemap/${id}.xml</loc><lastmod>${lastmod}</lastmod></sitemap>`,
  )
  .join("\n")}
</sitemapindex>
`;
  return new Response(body, {
    headers: { "Content-Type": "application/xml; charset=utf-8" },
  });
}
